pub enum StaticVal {
    Kw(&'static str),
    Num(f64, &'static str),
    Hex(&'static str),
    Literal(&'static str),
    RingShadow,
}

pub fn resolve_static_rule(
    modifiers: &[SpannedModifier],
    utility_token: &str,
    span: Span,
) -> Option<Vec<UtilityRule>> {
    let idx = STATIC_RULES
        .binary_search_by_key(&utility_token, |&(k, _, _)| k)
        .ok()?;
    let (_, selector, entries) = STATIC_RULES[idx];

    // 伴生选择器（`divide-*` 的相邻子元素、`placeholder-*` 的 `::placeholder`）
    // 以额外修饰符的形式挂上去，与模式解析路径的表达方式保持一致。
    let mut mods: smallvec::SmallVec<[SpannedModifier; 2]> = modifiers.iter().cloned().collect();
    if let Some(sel) = selector {
        mods.push(SpannedModifier::new(
            Modifier::CustomSelector(sel.to_string()),
            span,
        ));
    }

    let mut rules = Vec::with_capacity(entries.len());
    for &(ref prop, val) in entries {
        let uval = match val {
            StaticVal::Kw(s) => UtilityValue::Keyword(s),
            StaticVal::Num(v, u) => UtilityValue::Numeric(v, u),
            StaticVal::Hex(s) => crate::css::tw::resolver::hex(s),
            StaticVal::Literal(s) => UtilityValue::ArbitraryLiteral(s.to_string()),
            StaticVal::RingShadow => {
                UtilityValue::Keyword(crate::css::tw::resolver::RING_BOX_SHADOW)
            }
        };
        rules.push(make_rule(mods.clone(), *prop, uval, span).ok()?);
    }
    Some(rules)
}
